package com.resumebuilder.model;

public class GenerateResumeRequest {
    private Long userId;
    private String content;

    public GenerateResumeRequest() {
    }

    public GenerateResumeRequest(Long userId, String content) {
        this.userId = userId;
        this.content = content;
    }

    public Long getUserId() {
        return userId;
    }

    public void setUserId(Long userId) {
        this.userId = userId;
    }

    public String getContent() {
        return content;
    }

    public void setContent(String content) {
        this.content = content;
    }
}

package com.resumebuilder.model;

import com.fasterxml.jackson.annotation.JsonAnySetter;
import com.fasterxml.jackson.annotation.JsonProperty;

public class GenerateResumeRequest {
    @JsonProperty("userId")
    private Long userId;

    @JsonProperty("content")
    private String content;

    public GenerateResumeRequest() {
    }

    public GenerateResumeRequest(Long userId, String content) {
        this.userId = userId;
        this.content = content;
    }

    public Long getUserId() {
        return userId;
    }

    public void setUserId(Long userId) {
        this.userId = userId;
    }

    public String getContent() {
        return content;
    }

    public void setContent(String content) {
        this.content = content;
    }

    @JsonAnySetter
    public void handleUnknownProperty(String name, Object value) {
        if (name.equals("output[0].content[0].text")) {
            this.content = (String) value;
        }
    }
}
